package com.pulsbreath.android;
import android.Manifest;import android.bluetooth.*;import android.bluetooth.le.*;import android.content.*;import android.content.pm.PackageManager;import android.os.*;import java.util.*;
public final class AndroidBleClient {
 public interface Listener{void onStatus(String s);void onJson(String json);}
 public static final UUID SERVICE=UUID.fromString("7a1e0001-8b4f-4d2a-9c21-1234567890ab"), CHARACTERISTIC=UUID.fromString("7a1e0002-8b4f-4d2a-9c21-1234567890ab");
 private final Context context;private final Listener listener;private BluetoothLeScanner scanner;private BluetoothGatt gatt;private boolean scanning;
 public AndroidBleClient(Context c,Listener l){context=c.getApplicationContext();listener=l;}
 public void start(){BluetoothManager bm=(BluetoothManager)context.getSystemService(Context.BLUETOOTH_SERVICE);BluetoothAdapter a=bm==null?null:bm.getAdapter();if(a==null||!a.isEnabled()){listener.onStatus("Увімкніть Bluetooth");return;}scanner=a.getBluetoothLeScanner();if(scanner==null){listener.onStatus("BLE-сканер недоступний");return;}try{scanner.startScan(null,new ScanSettings.Builder().setScanMode(ScanSettings.SCAN_MODE_LOW_LATENCY).build(),scanCallback);scanning=true;listener.onStatus("Пошук XIAO-C6 / MR60BHA2…");new Handler(Looper.getMainLooper()).postDelayed(()->{if(scanning)stopScan();},15000);}catch(SecurityException e){listener.onStatus("Немає дозволу Bluetooth: "+e.getMessage());}}
 private final ScanCallback scanCallback=new ScanCallback(){@Override public void onScanResult(int type,ScanResult result){BluetoothDevice d=result.getDevice();String name="";try{name=d.getName();}catch(SecurityException ignored){}boolean uuid=false;List<ParcelUuid> us=result.getScanRecord()==null?null:result.getScanRecord().getServiceUuids();if(us!=null)for(ParcelUuid u:us)if(SERVICE.equals(u.getUuid()))uuid=true;if("XIAO-C6".equals(name)||"MR60BHA2".equals(name)||uuid){stopScan();try{gatt=d.connectGatt(context,false,gattCallback, BluetoothDevice.TRANSPORT_LE);listener.onStatus("Підключення BLE до "+name+"…");}catch(SecurityException e){listener.onStatus("Немає дозволу Bluetooth: "+e.getMessage());}}}@Override public void onScanFailed(int code){listener.onStatus("BLE scan failed: "+code);}};
 private final BluetoothGattCallback gattCallback=new BluetoothGattCallback(){@Override public void onConnectionStateChange(BluetoothGatt g,int status,int state){if(state==BluetoothProfile.STATE_CONNECTED){listener.onStatus("BLE підключено; пошук сервісу…");g.discoverServices();}else if(state==BluetoothProfile.STATE_DISCONNECTED){listener.onStatus("BLE відключено");closeGatt();}}@Override public void onServicesDiscovered(BluetoothGatt g,int status){BluetoothGattService s=g.getService(SERVICE);BluetoothGattCharacteristic c=s==null?null:s.getCharacteristic(CHARACTERISTIC);if(c==null){listener.onStatus("Не знайдено BLE service/characteristic UUID. Перевірте прошивку.");return;}try{g.setCharacteristicNotification(c,true);BluetoothGattDescriptor d=c.getDescriptor(UUID.fromString("00002902-0000-1000-8000-00805f9b34fb"));if(d!=null){d.setValue(BluetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE);g.writeDescriptor(d);}listener.onStatus("BLE підключено, очікування показників…");}catch(SecurityException e){listener.onStatus("BLE permission: "+e.getMessage());}}@Override public void onCharacteristicChanged(BluetoothGatt g,BluetoothGattCharacteristic c){byte[] b=c.getValue();if(b!=null)listener.onJson(new String(b,java.nio.charset.StandardCharsets.UTF_8));}@Override public void onCharacteristicChanged(BluetoothGatt g,BluetoothGattCharacteristic c,byte[] value){if(value!=null)listener.onJson(new String(value,java.nio.charset.StandardCharsets.UTF_8));}};
 private void stopScan(){if(scanner!=null&&scanning){try{scanner.stopScan(scanCallback);}catch(SecurityException ignored){}scanning=false;}}
 public void stop(){stopScan();closeGatt();}
 private void closeGatt(){if(gatt!=null){try{gatt.disconnect();gatt.close();}catch(SecurityException ignored){}gatt=null;}}
}
